#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Run from the repo root so .env lands there (it is git-ignored).
cd "$(dirname "$0")/.."

banner "ChargeOnSolar: device access"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Home network"
say "The HomeWizard P1 meter only answers on your home"
say "network, so this Mac must be connected to it (Wi-Fi or cable, not a hotspot)."
if ! confirm "Is this Mac on your home network right now?"; then
  warn "Connect to your home network and run this wizard again."
  exit 1
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Zaptec: login"
say "ChargeOnSolar talks to the Go 2 through Zaptec's cloud API, using your Zaptec account."
open_url "https://portal.zaptec.com"
step "Log in with the account you use in the Zaptec app, to be sure it works."
while true; do
  ask ZAPTEC_USERNAME "Zaptec username (email):"
  ask_secret ZAPTEC_PASSWORD "Zaptec password (hidden):"
  say "Testing the login against api.zaptec.com…"
  # Password goes via stdin, not the command line, so it never shows in `ps`.
  code=$(printf '%s' "$ZAPTEC_PASSWORD" | curl -s -o /dev/null -w '%{http_code}' --max-time 15 \
    -X POST https://api.zaptec.com/oauth/token \
    --data-urlencode grant_type=password \
    --data-urlencode "username=$ZAPTEC_USERNAME" \
    --data-urlencode "password@-" || true)
  if [[ "$code" == "200" ]]; then
    printf '  %s✓ Zaptec accepted the login%s\n' "$GREEN" "$RESET"
    break
  fi
  warn "Zaptec rejected the login (HTTP ${code:-no answer})."
  note "If your account uses two-step verification, this API login may not work; tell Claude."
  if confirm "Save these values anyway?"; then
    SKIPPED+=("Zaptec: login test failed (HTTP ${code:-none})")
    break
  fi
done
write_env ZAPTEC_USERNAME "$ZAPTEC_USERNAME"
write_env ZAPTEC_PASSWORD "$ZAPTEC_PASSWORD"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Zaptec: installation role"
say "Reading the Sense / load-balancing settings needs owner or admin rights on the"
say "installation, not just access to the charger."
step "In the portal, open your installation (the site, not the charger)."
step "Check that you can see and change its settings, e.g. available current or load balancing."
note "Menu names may differ from this description; you're looking for installation-level settings."
if ! confirm "Can you see and change the installation's settings?"; then
  SKIPPED+=("Zaptec: get owner/admin rights on the installation (ask your installer)")
  warn "Noted. Ask your installer to give your account owner/admin rights."
fi
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Enphase: developer app"
say "ChargeOnSolar reads Enphase through the Cloud API v4, on the free Watt plan."
say "For that you need your own (free) developer account and an application."
open_url "https://developer-v4.enphase.com/signup"
step "Sign up, then activate the account through the link Enphase emails you."
note "This is a separate account from your Enlighten (Enphase app) login."
pause "Press Enter when your developer account is active"
open_url "https://developer-v4.enphase.com/admin/applications"
step "Create an application. Plan: Watt (the free one). Name: ChargeOnSolar."
step "Access control: tick System Details, Site level Production Monitoring"
step "and Site level Consumption Monitoring."
step "Open the application to see its API Key, Client ID and Client Secret."
note "Exact labels on that page may differ slightly."
ask_secret ENPHASE_API_KEY "API Key (hidden):"
ask ENPHASE_CLIENT_ID "Client ID:"
ask_secret ENPHASE_CLIENT_SECRET "Client Secret (hidden):"
write_env ENPHASE_API_KEY "$ENPHASE_API_KEY"
write_env ENPHASE_CLIENT_ID "$ENPHASE_CLIENT_ID"
write_env ENPHASE_CLIENT_SECRET "$ENPHASE_CLIENT_SECRET"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Enphase: allow ChargeOnSolar to read your system"
ENPHASE_REDIRECT="https://api.enphaseenergy.com/oauth/redirect_uri"
auth=true
if [[ -n "$(_existing ENPHASE_REFRESH_TOKEN || true)" ]]; then
  confirm "Enphase is already authorized. Authorize again?" || auth=false
fi
while $auth; do
  say "You'll log in with your normal Enlighten account (the Enphase app login)"
  say "and allow the ChargeOnSolar application to read your system."
  open_url "https://api.enphaseenergy.com/oauth/authorize?response_type=code&client_id=${ENPHASE_CLIENT_ID}&redirect_uri=${ENPHASE_REDIRECT}"
  step "Log in and approve the access request."
  step "Your browser then lands on api.enphaseenergy.com/oauth/redirect_uri?code=…"
  step "The page itself may look empty or like an error; that's fine."
  step "Copy the FULL address from the browser's address bar."
  ask ENPHASE_REDIRECT_URL "Paste the address:"
  code=$(printf '%s' "$ENPHASE_REDIRECT_URL" | grep -o 'code=[^&]*' | head -n1 | sed 's/^code=//' || true)
  if [[ -z "$code" ]]; then
    warn "No code= found in that address."
    confirm "Try again?" && continue
    SKIPPED+=("Enphase: authorization not done (re-run this wizard)"); break
  fi
  say "Exchanging the code for tokens…"
  # Credentials go via file descriptors, so they never show in `ps`.
  basic=$(printf '%s:%s' "$ENPHASE_CLIENT_ID" "$ENPHASE_CLIENT_SECRET" | base64 | tr -d '\n')
  tok=$(curl -s --max-time 20 -X POST \
    -K <(printf 'url = "https://api.enphaseenergy.com/oauth/token?grant_type=authorization_code&redirect_uri=%s&code=%s"\n' "$ENPHASE_REDIRECT" "$code") \
    -H @<(printf 'Authorization: Basic %s' "$basic") || true)
  access=$(printf '%s' "$tok" | grep -o '"access_token" *: *"[^"]*"' | sed 's/.*: *"//; s/"$//' || true)
  refresh=$(printf '%s' "$tok" | grep -o '"refresh_token" *: *"[^"]*"' | sed 's/.*: *"//; s/"$//' || true)
  if [[ -z "$access" || -z "$refresh" ]]; then
    warn "Enphase didn't return tokens. The code may have expired or been used already."
    err=$(printf '%s' "$tok" | grep -o '"error[a-z_]*" *: *"[^"]*"' | tr '\n' ' ' || true)
    note "Enphase said: ${err:-no error message (response not shown, it may contain secrets)}"
    confirm "Try again (you'll log in once more)?" && continue
    SKIPPED+=("Enphase: token exchange failed (re-run this wizard)"); break
  fi
  printf '  %s✓ Enphase authorized ChargeOnSolar%s\n' "$GREEN" "$RESET"
  write_env ENPHASE_ACCESS_TOKEN "$access"
  write_env ENPHASE_REFRESH_TOKEN "$refresh"

  say "Looking up your system ID (uses 1 of the 1,000 monthly calls)…"
  systems=$(curl -s --max-time 20 \
    -K <(printf 'url = "https://api.enphaseenergy.com/api/v4/systems?key=%s"\n' "$ENPHASE_API_KEY") \
    -H @<(printf 'Authorization: Bearer %s' "$access") || true)
  ids=$(printf '%s' "$systems" | grep -o '"system_id" *: *[0-9]*' | grep -o '[0-9]*$' || true)
  count=$(printf '%s' "$ids" | grep -c . || true)
  if [[ "$count" == "1" ]]; then
    printf '  %s✓ found your system%s  ID: %s\n' "$GREEN" "$RESET" "$ids"
    write_env ENPHASE_SYSTEM_ID "$ids"
  elif [[ "$count" -gt 1 ]]; then
    say "Several systems found: $(printf '%s' "$ids" | tr '\n' ' ')"
    ask ENPHASE_SYSTEM_ID "Which system ID is your home?"
    write_env ENPHASE_SYSTEM_ID "$ENPHASE_SYSTEM_ID"
  else
    warn "Couldn't read your system list."
    note "Answer: $(printf '%s' "$systems" | head -c 200)"
    SKIPPED+=("Enphase: system ID not found (tell Claude)")
  fi
  break
done

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "HomeWizard: P1 meter address"
step "In the HomeWizard Energy app, open the P1 meter's device information."
note "Roughly: Settings → Meters → your P1 meter. Menu names may differ."
step "Note its IP address, and check the firmware is 6.x or newer (needed for API v2)."
while true; do
  ask HOMEWIZARD_HOST "P1 meter IP address:"
  # Before pairing, API v2 answers 401 "user:unauthorized"; that still proves v2 is there.
  api2=$(curl -sk --max-time 8 -H 'X-Api-Version: 2' "https://$HOMEWIZARD_HOST/api" || true)
  if [[ "$api2" == *"product_type"* || "$api2" == *"user:unauthorized"* ]]; then
    # Firmware details come from the old v1 API, if it happens to be enabled.
    api=$(curl -s --max-time 5 "http://$HOMEWIZARD_HOST/api" || true)
    [[ "$api2" == *"product_type"* ]] && api="$api2"
    fw=$(printf '%s' "$api" | grep -o '"firmware_version" *: *"[^"]*"' | sed 's/.*: *"//; s/"$//' || true)
    printf '  %s✓ P1 meter found, API v2 available%s  firmware: %s\n' "$GREEN" "$RESET" "${fw:-unknown}"
    break
  fi
  warn "No HomeWizard API v2 answered at https://$HOMEWIZARD_HOST/api."
  note "Check the IP address, and update the meter's firmware in the app if it's below 6.x."
  if confirm "Save this address anyway?"; then
    SKIPPED+=("HomeWizard: API v2 not reachable at $HOMEWIZARD_HOST")
    break
  fi
done
write_env HOMEWIZARD_HOST "$HOMEWIZARD_HOST"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "HomeWizard: pairing"
pair=true
if [[ -n "$(_existing HOMEWIZARD_TOKEN || true)" ]]; then
  confirm "A HomeWizard token is already saved. Pair again?" || pair=false
fi
while $pair; do
  say "Go to the P1 meter. When you press Enter, the wizard tries to pair for 40 seconds."
  say "During that time, ${BOLD}press the button on the P1 meter${RESET} once."
  pause "Press Enter, then press the button on the meter"
  token=""
  for ((i = 40; i > 0; i--)); do
    printf '\r  %swaiting for the button… %2ss%s ' "$DIM" "$i" "$RESET"
    resp=$(curl -sk --max-time 3 -X POST "https://$HOMEWIZARD_HOST/api/user" \
      -H 'X-Api-Version: 2' -H 'Content-Type: application/json' \
      -d '{"name":"local/chargeonsolar"}' || true)
    token=$(printf '%s' "$resp" | grep -o '"token" *: *"[^"]*"' | sed 's/.*: *"//; s/"$//' || true)
    [[ -n "$token" ]] && break
    sleep 1
  done
  printf '\n'
  if [[ -n "$token" ]]; then
    printf '  %s✓ paired with the P1 meter%s\n' "$GREEN" "$RESET"
    write_env HOMEWIZARD_TOKEN "$token"
    break
  fi
  warn "No token received. The button press may have been missed."
  if ! confirm "Try again?"; then
    SKIPPED+=("HomeWizard: pairing not done (re-run this wizard)")
    break
  fi
done

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Meter cupboard: what's on the P1 port"
say "The smart meter has one P1 port. Both the HomeWizard meter and the Zaptec Sense"
say "may want it, and that decides how the Sense can be used."
step "Look at the smart meter's P1 port and follow the cable(s)."
say ""
say "  1) Only the HomeWizard P1 meter"
say "  2) Only the Zaptec Sense"
say "  3) A splitter, with both the HomeWizard meter and the Sense on it"
say "  4) Something else (the Sense measures with clamps, not via P1, etc.)"
choice=""
while [[ ! "$choice" =~ ^[1-4]$ ]]; do
  read -r -p "  Choose 1-4: " choice || true
done
case "$choice" in
  1) setup="homewizard-only" ;;
  2) setup="sense-only" ;;
  3) setup="splitter-both" ;;
  4) ask METER_P1_OTHER "Describe it briefly:"; setup="other: ${METER_P1_OTHER}" ;;
esac
write_env METER_P1_SETUP "$setup"

finish
say "Next: tell Claude the wizard is done, so it can run the checks and record the facts."
printf '\n'
}

run_wizard "$@"; exit
